create or replace function public.can_upload_developer_client_property_photo_rc1(p_client_id uuid,p_property_id uuid,p_object_name text) returns boolean language plpgsql security definer set search_path=public set row_security=off stable as $$ declare v_user uuid; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then return false;end if;select user_id into v_user from public.clients where id=p_client_id;if v_user is null then return false;end if;if not exists(select 1 from public.properties where id=p_property_id and client_id=p_client_id) then return false;end if;return split_part(p_object_name,'/',1)=v_user::text and split_part(p_object_name,'/',2)='developer-property' and split_part(p_object_name,'/',3)=p_property_id::text;end $$;
create or replace function public.set_developer_client_property_photo_rc1(p_client_id uuid,p_property_id uuid,p_photo_path text,p_photo_url text) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501';end if;if not exists(select 1 from public.properties where id=p_property_id and client_id=p_client_id) then raise exception 'PROPERTY_NOT_FOUND';end if;if p_photo_path is not null and not public.can_upload_developer_client_property_photo_rc1(p_client_id,p_property_id,p_photo_path) then raise exception 'INVALID_PROPERTY_PHOTO_PATH';end if;update public.properties set photo_path=nullif(trim(p_photo_path),''),photo_url=nullif(trim(p_photo_url),''),updated_at=now() where id=p_property_id and client_id=p_client_id;return jsonb_build_object('property_id',p_property_id,'photo_path',nullif(trim(p_photo_path),''),'photo_url',nullif(trim(p_photo_url),''));end $$;
revoke all on function public.can_upload_developer_client_property_photo_rc1(uuid,uuid,text) from public,anon;revoke all on function public.set_developer_client_property_photo_rc1(uuid,uuid,text,text) from public,anon;grant execute on function public.can_upload_developer_client_property_photo_rc1(uuid,uuid,text) to authenticated,service_role;grant execute on function public.set_developer_client_property_photo_rc1(uuid,uuid,text,text) to authenticated,service_role;
drop policy if exists property_photos_developer_insert on storage.objects;create policy property_photos_developer_insert on storage.objects for insert to authenticated with check(bucket_id='property-photos' and split_part(name,'/',2)='developer-property' and exists(select 1 from public.clients c join public.properties p on p.client_id=c.id where c.user_id::text=split_part(name,'/',1) and p.id::text=split_part(name,'/',3) and public.can_upload_developer_client_property_photo_rc1(c.id,p.id,name)));
